-- restore-metadata.sql — 回退「下架 13 面板」的元数据(由 _dump-dropped-docs.java 生成)
-- 用法:两账套分别执行;脚本幂等(先删后插,只针对这 13 个面板编码与其面板名译名)
SET NOCOUNT ON;
GO
IF DB_NAME() = N'master' USE HSDZ_MES;   -- 仅在未选定库时切正式库
GO

-- ══ yj_panel ══
DELETE FROM dbo.yj_panel WHERE panel_code IN ('QC_OP','QC_RECORD','QC_DISPOSAL','ROD_RETURN','LOT_TRACE');
GO
GO

-- ══ yj_field ══
DELETE FROM dbo.yj_field WHERE panel_code IN ('QC_OP','QC_RECORD','QC_DISPOSAL','ROD_RETURN','LOT_TRACE');
GO
SET IDENTITY_INSERT dbo.yj_field ON;
GO
GO
SET IDENTITY_INSERT dbo.yj_field OFF;
GO

-- ══ yj_role_panel ══
DELETE FROM dbo.yj_role_panel WHERE panel_code IN ('QC_OP','QC_RECORD','QC_DISPOSAL','ROD_RETURN','LOT_TRACE');
GO
SET IDENTITY_INSERT dbo.yj_role_panel ON;
GO
GO
SET IDENTITY_INSERT dbo.yj_role_panel OFF;
GO

-- ══ yj_translation(panel 名,scope='panel')══
DELETE FROM dbo.yj_translation WHERE scope = 'panel' AND ref_key IN (
  SELECT DISTINCT panel_name FROM dbo.yj_panel WHERE panel_code IN ('QC_OP','QC_RECORD','QC_DISPOSAL','ROD_RETURN','LOT_TRACE'));
-- 注:上面这句删的是「当前库里这 13 个面板的中文名」的全部译名;若同名面板还有别的,
--     迁移脚本用的是「无其它面板同名」守卫 —— 回退时如需精确,请按 CSV 里的 ref_key 逐条回插。
GO

